public class MachineLearningUsageTransportActionTests extends ESTestCase {
    public void testAddTrainedModelStatsHandlesMultipleDeployments() {
        Map<String, Object> usage = new HashMap<>();

        var deploymentConfig = TrainedModelConfigTests.createTestInstance("id1").build();
        var stats = new GetTrainedModelsStatsAction.Response.TrainedModelStats(
            "id1",
            TrainedModelSizeStatsTests.createRandom(),
            GetTrainedModelsStatsActionResponseTests.randomIngestStats(),
            randomIntBetween(0, 10),
            null,
            null
        );
        StatsAccumulator actualMemoryUsage = new StatsAccumulator();
        actualMemoryUsage.add(stats.getModelSizeStats().getModelSizeBytes());

        var modelsResponse = new GetTrainedModelsAction.Response(
            new QueryPage<>(List.of(deploymentConfig), 1, GetTrainedModelsAction.Response.RESULTS_FIELD)
        );

        var statsResponse = new GetTrainedModelsStatsAction.Response(
            new QueryPage<>(List.of(stats), 1, GetTrainedModelsStatsAction.Response.RESULTS_FIELD)
        );

        MachineLearningUsageTransportAction.addTrainedModelStats(modelsResponse, statsResponse, usage);
        @SuppressWarnings("unchecked")
        var expectedModelMemoryUsage = ((Map<String, Object>) usage.get("trained_models")).get(
            TrainedModelConfig.MODEL_SIZE_BYTES.getPreferredName()
        );
        assertThat(expectedModelMemoryUsage, is(actualMemoryUsage.asMap()));
    }
}

public class RestCatTrainedModelsActionTests extends ESTestCase {

    private RestCatTrainedModelsAction action;

    @Before
    public void setUpAction() {
        action = new RestCatTrainedModelsAction();
    }

    public void testBuildTableAccumulatedStats() {
        // GetTrainedModelsStatsActionResponseTests
        var deployment1 = new GetTrainedModelsStatsAction.Response.TrainedModelStats(
            "id1",
            new TrainedModelSizeStats(100, 200),
            GetTrainedModelsStatsActionResponseTests.randomIngestStats(),
            2,
            null,
            null
        );

        var deployment2 = new GetTrainedModelsStatsAction.Response.TrainedModelStats(
            "id1",
            new TrainedModelSizeStats(1, 2),
            GetTrainedModelsStatsActionResponseTests.randomIngestStats(),
            2,
            null,
            null
        );

        var configs = List.of(TrainedModelConfigTests.createTestInstance("id1").build());

        var table = action.buildTable(new FakeRestRequest(), List.of(deployment1, deployment2), configs, List.of());
        assertThat(table.getRows().get(0).get(0).value, is("id1"));
        // pipeline count
        assertThat(table.getRows().get(0).get(9).value, is(4));
        // ingest count
        assertThat(
            table.getRows().get(0).get(10).value,
            is(deployment1.getIngestStats().totalStats().ingestCount() + deployment2.getIngestStats().totalStats().ingestCount())
        );
        // ingest time in millis
        assertThat(
            table.getRows().get(0).get(11).value,
            is(
                deployment1.getIngestStats().totalStats().ingestTimeInMillis() + deployment2.getIngestStats()
                    .totalStats()
                    .ingestTimeInMillis()
            )
        );
        // ingest current
        assertThat(
            table.getRows().get(0).get(12).value,
            is(deployment1.getIngestStats().totalStats().ingestCurrent() + deployment2.getIngestStats().totalStats().ingestCurrent())
        );
        // ingest failed count
        assertThat(
            table.getRows().get(0).get(13).value,
            is(
                deployment1.getIngestStats().totalStats().ingestFailedCount() + deployment2.getIngestStats()
                    .totalStats()
                    .ingestFailedCount()
            )
        );
    }
}

public static Response createInstance() {
        int listSize = randomInt(10);
        List<Response.TrainedModelStats> trainedModelStats = Stream.generate(() -> randomAlphaOfLength(10))
            .limit(listSize)
            .map(
                id -> new Response.TrainedModelStats(
                    id,
                    randomBoolean() ? TrainedModelSizeStatsTests.createRandom() : null,
                    randomBoolean() ? randomIngestStats() : null,
                    randomIntBetween(0, 10),
                    randomBoolean() ? InferenceStatsTests.createTestInstance(id, null) : null,
                    randomBoolean() ? AssignmentStatsTests.randomDeploymentStats() : null
                )
            )
            .collect(Collectors.toList());
        return new Response(new QueryPage<>(trainedModelStats, randomLongBetween(listSize, 1000), RESULTS_FIELD));
    }

